import { PluncError, } from "../errors/pluncError";
import { ComponentFamilyTreeBrand, } from "../types";
function getInternalComponentFamilyTree(tree) {
    if ("data" in tree) {
        return tree;
    }
    throw new PluncError("ERR5");
}
export function createComponentLineage() {
    const genealogy = {
        data: {},
        [ComponentFamilyTreeBrand]: true,
    };
    return genealogy;
}
export function addRecordToComponentLineage(tree, parentId, childId) {
    const internalTree = getInternalComponentFamilyTree(tree);
    if (internalTree.data[parentId] === undefined) {
        internalTree.data[parentId] = {
            parent: null,
            children: [],
        };
    }
    internalTree.data[parentId].children.push(childId);
    if (internalTree.data[childId] === undefined) {
        internalTree.data[childId] = {
            parent: parentId,
            children: [],
        };
    }
}
export function lookupComponentLineage(tree, childId) {
    const internalTree = getInternalComponentFamilyTree(tree);
    if (internalTree.data[childId] === undefined)
        return [];
    const parents = [];
    let parent = internalTree.data[childId].parent;
    while (parent !== null) {
        parents.push(parent);
        parent = internalTree.data[parent].parent;
    }
    return parents;
}
export function whoAreTheChildrenOfComponent(tree, parentId) {
    const internalTree = getInternalComponentFamilyTree(tree);
    if (internalTree.data[parentId] === undefined)
        return [];
    return internalTree.data[parentId].children;
}
export function whoIsTheParentOfComponent(tree, childId) {
    const internalTree = getInternalComponentFamilyTree(tree);
    if (internalTree.data[childId] === undefined)
        return null;
    return internalTree.data[childId].parent;
}
export function whoAreTheSiblingsOfComponent(tree, componentId) {
    const internalTree = getInternalComponentFamilyTree(tree);
    if (internalTree.data[componentId] === undefined)
        return [];
    const parentId = internalTree.data[componentId].parent;
    if (parentId === null)
        return [];
    const siblings = internalTree.data[parentId].children.filter((childId) => childId !== componentId);
    return siblings;
}
