export function createPluncAppInternalRepresentation(id, name, config, library, registry) {
    const onReadyListeners = [];
    let ready = false;
    function emitReady() {
        ready = true;
        for (const listener of onReadyListeners) {
            listener();
        }
    }
    function isReady() {
        return ready;
    }
    function onReady(listener) {
        onReadyListeners.push(listener);
    }
    function getReadyListeners() {
        return onReadyListeners;
    }
    return {
        config,
        library,
        registry,
        name,
        id,
        getReadyListeners,
        emitReady,
        isReady,
        onReady,
    };
}
