import { PluncError, } from "../errors/pluncError";
export function createStagingElement(innerHtml) {
    const element = document.implementation.createHTMLDocument().body;
    // add custom property to indicate staging status
    Object.defineProperty(element, "$plStgCS", {
        value: false,
        writable: true,
        enumerable: false,
        configurable: false,
    });
    if (innerHtml) {
        element.innerHTML = innerHtml;
    }
    return element;
}
export function setStagingElementInnerHtml(stagingElement, html) {
    if (stagingElement.$plStgCS) {
        throw new PluncError("ERR1");
    }
    stagingElement.innerHTML = html;
}
export function getStagingElementInnerHtml(stagingElement) {
    if (stagingElement.$plStgCS) {
        throw new PluncError("ERR2");
    }
    return stagingElement.innerHTML;
}
export function commitStagingElementTo(stagingElement, targetElement) {
    if (stagingElement.$plStgCS) {
        throw new PluncError("ERR3");
    }
    while (stagingElement.firstChild) {
        targetElement.appendChild(stagingElement.firstChild);
    }
    stagingElement.$plStgCS = true;
}
